  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useMemo } from 'react';
  4→import { HeroReel } from '@/components/HeroReel';
  5→import { LadderGrid } from '@/components/LadderGrid';
  6→import { usePerception } from '@/lib/perception/context';
  7→import { projects, projectsBySlug } from '@/lib/projects';
  8→import { ProjectAdapter } from '@/lib/perception/adapter';
  9→import { useIsMobile } from '@/lib/hooks/useIsMobile';
 10→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
 11→
 12→// Hoisted static styles — avoids creating new objects on every render
 13→const scrollIndicatorTextStyle = {
 14→  color: '#8a8a8a',
 15→  fontFamily: 'var(--font-display)',
 16→  fontSize: '11px',
 17→  fontWeight: 600,
 18→  letterSpacing: '0.04em',
 19→  textTransform: 'uppercase' as const,
 20→  marginTop: '8px'
 21→};
 22→
 23→const gradientOverlayStyle = {
 24→  height: '250px',
 25→  background: 'linear-gradient(to bottom, #141414 0%, transparent 100%)',
 26→  zIndex: 95,
 27→  opacity: 0
 28→};
 29→
 30→const heroSectionStyle = {
 31→  maxWidth: 'var(--max-content-width)',
 32→  paddingLeft: 'var(--side-padding)',
 33→  paddingRight: 'var(--side-padding)',
 34→  paddingTop: 'clamp(102px, 10.2vw + 34px, 170px)',
 35→  paddingBottom: 'clamp(102px, 10.2vw + 34px, 170px)',
 36→};
 37→
 38→const heroTextWrapperStyle = { maxWidth: '900px' };
 39→
 40→const gridSectionStyle = {
 41→  maxWidth: 'var(--max-content-width)',
 42→  paddingLeft: 'var(--side-padding)',
 43→  paddingRight: 'var(--side-padding)',
 44→  paddingBottom: 'var(--space-lg)',
 45→};
 46→
 47→export default function HomePage() {
 48→  // Get perception state from context (sensor runs in PerceptionLayer)
 49→  const { archetype, confidence } = usePerception();
 50→
 51→  const { isMobile } = useIsMobile();
 52→  const prefersReducedMotion = usePrefersReducedMotion();
 53→
 54→  const [introVisible, setIntroVisible] = useState(false);
 55→
 56→  // Refs for scroll-driven DOM updates (no re-renders on scroll)
 57→  const scrollIndicatorRef = useRef<HTMLDivElement>(null);
 58→  const introTextRef = useRef<HTMLElement>(null);
 59→  const gradientOverlayRef = useRef<HTMLDivElement>(null);
 60→
 61→  // Hero height based on device - matches HeroReel component
 62→  const heroHeight = isMobile ? '50vh' : '70vh';
 63→  const heroHeightMultiplier = isMobile ? 0.5 : 0.7;
 64→
 65→  // Trigger intro animation on mount
 66→  useEffect(() => {
 67→    const timer = setTimeout(() => setIntroVisible(true), 100);
 68→    return () => clearTimeout(timer);
 69→  }, []);
 70→
 71→  // Listen for chatbot open/close via custom event (replaces MutationObserver)
 72→  useEffect(() => {
 73→    const scrollIndicator = scrollIndicatorRef.current;
 74→    if (!scrollIndicator) return;
 75→
 76→    const observer = new MutationObserver(() => {
 77→      const isOpen = document.body.hasAttribute('data-chatbot-open');
 78→      if (scrollIndicator) {
 79→        scrollIndicator.style.opacity = isOpen ? '0' : scrollIndicator.dataset.scrollOpacity || '1';
 80→        scrollIndicator.style.pointerEvents = isOpen ? 'none' : 'auto';
 81→      }
 82→    });
 83→
 84→    observer.observe(document.body, { attributes: true, attributeFilter: ['data-chatbot-open'] });
 85→    return () => observer.disconnect();
 86→  }, []);
 87→
 88→  // Scroll-driven opacity updates via direct DOM manipulation (no React re-renders)
 89→  useEffect(() => {
 90→    const handleScroll = () => {
 91→      const scrollY = window.scrollY;
 92→
 93→      // Fade out scroll indicator between 0-300px scroll
 94→      const scrollIndicatorOp = Math.max(0, 1 - (scrollY / 300));
 95→      if (scrollIndicatorRef.current) {
 96→        scrollIndicatorRef.current.dataset.scrollOpacity = String(scrollIndicatorOp);
 97→        // Only update DOM if chatbot isn't overriding
 98→        if (!document.body.hasAttribute('data-chatbot-open')) {
 99→          scrollIndicatorRef.current.style.opacity = String(scrollIndicatorOp);
100→          scrollIndicatorRef.current.style.pointerEvents = scrollIndicatorOp === 0 ? 'none' : 'auto';
101→        }
102→      }
103→
104→      // Fade out intro text right before it overlaps navigation
105→      const fadeStart = 600;
106→      const fadeEnd = 800;
107→      let introOp = 1;
108→      if (scrollY > fadeStart) {
109→        introOp = Math.max(0, 1 - ((scrollY - fadeStart) / (fadeEnd - fadeStart)));
110→      }
111→      if (introTextRef.current) {
112→        introTextRef.current.style.opacity = String(introOp);
113→      }
114→
115→      // Fade gradient overlay for content scrolling under navigation
116→      const currentHeroHeight = window.innerHeight * heroHeightMultiplier;
117→      const contentTopPosition = currentHeroHeight - scrollY;
118→      const navHeight = 200;
119→      let mainTopOp = 1;
120→      if (contentTopPosition < navHeight) {
121→        const fadeDistance = 150;
122→        const distanceIntoNav = navHeight - contentTopPosition;
123→        mainTopOp = Math.max(0, 1 - (distanceIntoNav / fadeDistance));
124→      }
125→      if (gradientOverlayRef.current) {
126→        gradientOverlayRef.current.style.opacity = mainTopOp < 1 ? String((1 - mainTopOp) * 0.95) : '0';
127→      }
128→    };
129→
130→    window.addEventListener('scroll', handleScroll, { passive: true });
131→    return () => window.removeEventListener('scroll', handleScroll);
132→  }, [heroHeightMultiplier]);
133→
134→  // Find General Reel for hero (O(1) Map lookup)
135→  const heroProject = projectsBySlug.get('general-reel');
136→
137→  // Hero statement - authentic, consistent regardless of mode
138→  const heroStatement = "Sixteen years. Feature films, commercials, real-time engines—each frame a problem of light solved in pixels. This is the work.";
139→
140→  // Adapt project order based on visitor archetype
141→  // Only adapts when confidence > 0.5 to avoid premature/unstable reordering
142→  const adaptedProjects = useMemo(() => {
143→    const gridProjects = projects.filter(p => p.slug !== 'general-reel');
144→
145→    // Confidence threshold: don't adapt on weak signal
146→    if (confidence < 0.5 || !archetype) {
147→      return gridProjects;
148→    }
149→
150→    return ProjectAdapter.adaptProjectOrder(gridProjects, archetype);
151→  }, [archetype, confidence]);
152→
153→  return (
154→    <>
155→      {/* Hero Reel - Fixed position, crossfades on scroll, below navigation */}
156→      {heroProject && (
157→        <HeroReel
158→          videoId={heroProject.videoId}
159→          videoHash={heroProject.videoHash}
160→          startTime={heroProject.startTime}
161→          thumbnail={heroProject.thumbnail}
162→        />
163→      )}
164→
165→      {/* Scroll indicator - positioned right below hero reel, hidden when chatbot is open */}
166→      <div
167→        ref={scrollIndicatorRef}
168→        className="fixed left-0 right-0 flex flex-col items-center"
169→        style={{
170→          top: `calc(${heroHeight} - 60px)`,
171→          zIndex: 90,
172→          opacity: 1,
173→          transition: 'opacity 0.3s ease-out'
174→        }}
175→      >
176→        <svg
177→          className="scroll-chevron"
178→          width="24"
179→          height="24"
180→          viewBox="0 0 24 24"
181→          fill="none"
182→          stroke="#8a8a8a"
183→          strokeWidth="2"
184→          strokeLinecap="round"
185→          strokeLinejoin="round"
186→        >
187→          <polyline points="6 9 12 15 18 9" />
188→        </svg>
189→        <p style={scrollIndicatorTextStyle}>
190→          Scroll
191→        </p>
192→      </div>
193→
194→      {/* Gradient fade overlay for content scrolling under navigation */}
195→      <div
196→        ref={gradientOverlayRef}
197→        className="fixed top-0 left-0 right-0 pointer-events-none"
198→        style={gradientOverlayStyle}
199→      />
200→
201→      {/* Main content - starts below viewport, scrolls up */}
202→      <main className="min-h-screen relative" style={{ marginTop: heroHeight, zIndex: 50, backgroundColor: '#141414' }}>
203→        {/* Hero Statement - Isolated quote with generous whitespace (Pentagram style) */}
204→        <section
205→          ref={introTextRef}
206→          className="mx-auto"
207→          style={heroSectionStyle}
208→        >
209→          <div style={heroTextWrapperStyle}>
210→            {/* Hero Statement - Editorial serif quote style, Pentagram-tight heading */}
211→            <h1
212→              style={{
213→                color: '#a0a0a0',
214→                fontFamily: 'var(--font-lora)',
215→                fontWeight: 400,
216→                fontStyle: 'italic',
217→                fontSize: 'clamp(22px, 3.5vw, 38px)',
218→                lineHeight: 1.2,
219→                letterSpacing: '0.005em',
220→                opacity: introVisible ? 1 : 0,
221→                transform: introVisible ? 'translateY(0)' : `translateY(${isMobile ? 20 : 30}px)`,
222→                transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1), transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1)'
223→              }}
224→            >
225→              {heroStatement}
226→            </h1>
227→          </div>
228→        </section>
229→
230→        {/* Ladder Grid - Golden ratio spacing (excludes hero reel to avoid duplication) */}
231→        <section
232→          className="mx-auto"
233→          style={gridSectionStyle}
234→        >
235→          <LadderGrid projects={adaptedProjects} />
236→        </section>
237→      </main>
238→    </>
239→  );
240→}
241→

  1→@import "tailwindcss";
  2→
  3→/**
  4→ * GOLDEN RATIO DESIGN SYSTEM
  5→ *
  6→ * Spacing follows Fibonacci sequence (approximates φ = 1.618):
  7→ * - 21, 34, 55, 89, 144, 233px
  8→ * - Each value × 1.618 ≈ next value
  9→ *
 10→ * Blends production warmth with Pentagram refinement:
 11→ * - Dark theme with warm amber accent
 12→ * - Golden ratio spacing throughout
 13→ * - Editorial typography with warmth
 14→ * - Refined interactions
 15→ */
 16→
 17→:root {
 18→  /* Golden Ratio: φ = 1.618, 1/φ = 0.618 */
 19→  --phi: 1.618;
 20→  --phi-inverse: 0.618;
 21→
 22→  /* Fibonacci spacing scale (each × φ ≈ next) */
 23→  --space-xs: 21px;    /* Fibonacci */
 24→  --space-sm: 34px;    /* 21 × 1.618 ≈ 34 */
 25→  --space-md: 55px;    /* 34 × 1.618 ≈ 55 */
 26→  --space-lg: 89px;    /* 55 × 1.618 ≈ 89 */
 27→  --space-xl: 144px;   /* 89 × 1.618 ≈ 144 */
 28→  --space-2xl: 233px;  /* 144 × 1.618 ≈ 233 */
 29→
 30→  /* Typography - Helvetica Neue alternative */
 31→  /* Inter: neo-grotesque sans-serif, clean, neutral, screen-optimized */
 32→  --font-display: var(--font-inter), 'Inter', sans-serif;
 33→  --font-body: var(--font-inter), 'Inter', sans-serif;
 34→
 35→  /* Color palette - Dark with warm accent */
 36→  --background: #141414;
 37→  --foreground: #b8b8b8;
 38→  --text-primary: #e8e8e8;
 39→  --text-secondary: #8a8a8a;  /* Consolidated from #888888, #8a8a8a */
 40→  --text-muted: #6a6a6a;      /* Consolidated from #666666, #6a6a6a */
 41→  --text-dim: #5a5a5a;        /* NEW: For subtle labels, tags */
 42→  --border: #2a2a2a;
 43→  --border-subtle: #222222;   /* NEW: For subtle dividers */
 44→  --surface: #1a1a1a;         /* NEW: Elevated surface (cards, tags) */
 45→  --accent: #d4a853;          /* Warm gold - refined amber */
 46→  --accent-subtle: rgba(212, 168, 83, 0.15);
 47→
 48→  /* ═══════════════════════════════════════════════════════════════
 49→     COLOR HIERARCHY MANTRA
 50→     Information hierarchy = Color hierarchy
 51→
 52→     PRIMARY:   --text-primary (#e8e8e8) — Titles, headings, anchors
 53→     SECONDARY: --grey-500 (#7a7a7a)     — Descriptions, body content
 54→     TERTIARY:  --text-dim (#5a5a5a)     — Metadata, labels, footnotes
 55→
 56→     Rule: Brighter = more important. Dimmer = supporting context.
 57→     ═══════════════════════════════════════════════════════════════ */
 58→
 59→  /* Grey scale - Deterministic (use these, not hex values) */
 60→  --grey-50: #f0f0f0;   /* Brightest text */
 61→  --grey-100: #e8e8e8;  /* Primary text (= --text-primary) — TITLES */
 62→  --grey-200: #c0c0c0;  /* Emphasis text */
 63→  --grey-300: #a0a0a0;  /* Light secondary */
 64→  --grey-400: #8a8a8a;  /* Secondary text (= --text-secondary) */
 65→  --grey-500: #7a7a7a;  /* Medium grey — DESCRIPTIONS */
 66→  --grey-600: #6a6a6a;  /* Muted text (= --text-muted) */
 67→  --grey-700: #5a5a5a;  /* Dim text (= --text-dim) — METADATA */
 68→  --grey-800: #3a3a3a;  /* Separator dots */
 69→  --grey-900: #2a2a2a;  /* Borders (= --border) */
 70→
 71→  /* Micro spacing - for elements smaller than Fibonacci scale */
 72→  --space-micro: 4px;   /* Padding inside small elements */
 73→  --space-tiny: 8px;    /* Small gaps */
 74→  --space-small: 13px;  /* 21 / phi ≈ 13 */
 75→
 76→  /* Border radius scale - 3 values only */
 77→  --radius-sm: 4px;     /* Tags, buttons, code blocks */
 78→  --radius-md: 6px;     /* Thumbnails, cards */
 79→  --radius-full: 50%;   /* Circles, avatars */
 80→
 81→  /* Standardized transitions */
 82→  --transition-fast: 200ms ease-out;
 83→  --transition-base: 300ms ease-out;
 84→  --transition-smooth: 400ms cubic-bezier(0.25, 0.1, 0.25, 1);
 85→
 86→  /* Standardized hover opacity */
 87→  --hover-dim: 0.6;
 88→}
 89→
 90→@theme inline {
 91→  --color-background: var(--background);
 92→  --color-foreground: var(--foreground);
 93→  --font-sans: var(--font-inter);
 94→
 95→  /* Golden ratio spacing */
 96→  --spacing-section: var(--space-lg);  /* 89px */
 97→  --spacing-gutter: var(--space-md);   /* 55px */
 98→
 99→  /* Layout - balanced width */
100→  --max-content-width: 1600px;
101→  --side-padding: clamp(24px, 3vw, 80px);     /* Fluid: scales with viewport */
102→  --side-padding-md: clamp(34px, 4vw, 100px);  /* Fluid: scales with viewport */
103→}
104→
105→/* Typography */
106→body {
107→  background: var(--background);
108→  color: var(--foreground);
109→  font-family: var(--font-body), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
110→  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
111→  -webkit-font-smoothing: antialiased;
112→  -moz-osx-font-smoothing: grayscale;
113→}
114→
115→h1, h2, h3, h4, h5, h6, p {
116→  margin: 0;
117→  font-weight: 400;
118→}
119→
120→button {
121→  border: none;
122→  font: inherit;
123→  cursor: pointer;
124→}
125→
126→html {
127→  scroll-behavior: smooth;
128→}
129→
130→/* ===========================================
131→   PROJECT CARD INTERACTIONS
132→   =========================================== */
133→
134→/* Hover overlay and transitions handled inline in ProjectCard.tsx and VideoThumbnail.tsx */
135→/* This keeps all visual logic colocated with the component for easier maintenance */
136→
137→/* ===========================================
138→   NAVIGATION INTERACTIONS
139→   =========================================== */
140→
141→.nav-link {
142→  position: relative;
143→  display: inline-block;
144→  text-decoration: none;
145→  /* Reversed hover: full opacity by default, dims on hover */
146→  opacity: 1;
147→  transition: opacity var(--transition-smooth);
148→}
149→
150→@media (hover: hover) and (pointer: fine) {
151→  .nav-link:hover {
152→    opacity: var(--hover-dim);
153→  }
154→}
155→
156→/* Section headers - Light table effect */
157→.section-header-highlight {
158→  position: relative;
159→  display: inline-block;
160→  /* Light table: dimmed by default, reveals on hover */
161→  opacity: 0.5;
162→  transition: opacity var(--transition-smooth);
163→}
164→
165→@media (hover: hover) and (pointer: fine) {
166→  .section-header-highlight:hover {
167→    opacity: 1;
168→  }
169→}
170→
171→.nav-item-shift {
172→  transition: opacity var(--transition-smooth);
173→}
174→
175→/* Button arrow */
176→.button-arrow-shift {
177→  display: inline-flex;
178→  align-items: center;
179→  gap: var(--space-tiny);
180→}
181→
182→.button-arrow {
183→  transition: transform var(--transition-smooth), opacity var(--transition-smooth);
184→  opacity: 0.5;
185→}
186→
187→@media (hover: hover) and (pointer: fine) {
188→  .button-arrow-shift:hover .button-arrow {
189→    transform: translateX(4px);
190→    opacity: 1;
191→  }
192→}
193→
194→.gpu-accelerated {
195→  will-change: transform;
196→  transform: translateZ(0);
197→  backface-visibility: hidden;
198→}
199→
200→/* ===========================================
201→   ENTRANCE ANIMATIONS
202→   =========================================== */
203→
204→@keyframes fadeUp {
205→  from {
206→    opacity: 0;
207→    transform: translateY(21px);  /* Fibonacci */
208→  }
209→  to {
210→    opacity: 1;
211→    transform: translateY(0);
212→  }
213→}
214→
215→.project-card {
216→  opacity: 0;
217→  animation: fadeUp 0.7s ease-out forwards;
218→}
219→
220→.project-card:nth-child(1) { animation-delay: 0ms; }
221→.project-card:nth-child(2) { animation-delay: 80ms; }
222→.project-card:nth-child(3) { animation-delay: 160ms; }
223→.project-card:nth-child(4) { animation-delay: 240ms; }
224→.project-card:nth-child(5) { animation-delay: 320ms; }
225→.project-card:nth-child(6) { animation-delay: 400ms; }
226→
227→@keyframes fadeIn {
228→  from { opacity: 0; }
229→  to { opacity: 1; }
230→}
231→
232→.client-strip {
233→  animation: fadeIn 0.8s ease-out forwards;
234→  animation-delay: 200ms;
235→  opacity: 0;
236→}
237→
238→/* Scroll indicator */
239→@keyframes scrollFloat {
240→  0%, 100% {
241→    transform: translateY(0);
242→    opacity: 0.5;
243→  }
244→  50% {
245→    transform: translateY(6px);
246→    opacity: 0.8;
247→  }
248→}
249→
250→.scroll-chevron {
251→  animation: scrollFloat 2.8s ease-in-out infinite;
252→  will-change: transform, opacity;
253→}
254→
255→/* Chat typing indicator */
256→@keyframes typingPulse {
257→  0%, 100% {
258→    opacity: 0.3;
259→    transform: scale(1);
260→  }
261→  50% {
262→    opacity: 1;
263→    transform: scale(1.15);
264→  }
265→}
266→
267→.typing-dot {
268→  will-change: transform, opacity;
269→}
270→
271→/* Chat message entrance */
272→@keyframes chatMessageIn {
273→  from {
274→    opacity: 0;
275→    transform: translateY(13px);  /* --space-small: 21 / phi */
276→  }
277→  to {
278→    opacity: 1;
279→    transform: translateY(0);
280→  }
281→}
282→
283→.chat-message-enter {
284→  animation: chatMessageIn 0.3s ease-out forwards;
285→}
286→
287→/* Reduced motion */
288→@media (prefers-reduced-motion: reduce) {
289→  html {
290→    scroll-behavior: auto;
291→  }
292→
293→  *,
294→  *::before,
295→  *::after {
296→    animation-duration: 0.01ms !important;
297→    animation-iteration-count: 1 !important;
298→    transition-duration: 0.01ms !important;
299→  }
300→
301→  [aria-live="polite"] {
302→    transition: none !important;
303→  }
304→
305→  .nav-link,
306→  .project-title h3,
307→  .section-header-highlight,
308→  .project-card,
309→  .nav-item-shift,
310→  .button-arrow,
311→  .scroll-chevron,
312→  .typing-dot,
313→  .chat-message-enter {
314→    transition: none !important;
315→    transform: none !important;
316→    animation: none !important;
317→  }
318→}
319→
320→/* ===========================================
321→   FOCUS INDICATORS FOR ACCESSIBILITY
322→   =========================================== */
323→
324→/* Remove default focus ring */
325→:focus {
326→  outline: none;
327→}
328→
329→/* Focus-visible indicators for keyboard navigation */
330→:focus-visible {
331→  outline: 2px solid rgba(255, 255, 255, 0.5);
332→  outline-offset: 2px;
333→}
334→
335→/* Specific overrides for buttons and links */
336→button:focus-visible,
337→a:focus-visible {
338→  outline: 2px solid rgba(255, 255, 255, 0.5);
339→  outline-offset: 2px;
340→}
341→
342→/* Remove default focus ring on mouse click, keep for keyboard */
343→button:focus:not(:focus-visible),
344→a:focus:not(:focus-visible) {
345→  outline: none;
346→}
347→
348→/* ===========================================
349→   VIEW TRANSITIONS - Cinematic Page Crossfades
350→   =========================================== */
351→
352→/*
353→ * Design philosophy:
354→ * - Film dissolve feel, not flashy web animation
355→ * - Content: subtle crossfade with micro-scale for depth
356→ * - Navigation: fade only (no scale/position change - stays anchored)
357→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
358→ * - Easing: ease-in-out for cinematic linear-ish blend
359→ */
360→
361→/* Root (main content) transition */
362→::view-transition-old(root),
363→::view-transition-new(root) {
364→  animation-duration: 500ms;
365→  animation-timing-function: ease-in-out;
366→}
367→
368→/* Old page: fade out with slight scale down */
369→::view-transition-old(root) {
370→  animation-name: fade-and-scale-out;
371→}
372→
373→/* New page: fade in with slight scale up */
374→::view-transition-new(root) {
375→  animation-name: fade-and-scale-in;
376→}
377→
378→@keyframes fade-and-scale-out {
379→  from {
380→    opacity: 1;
381→    transform: scale(1);
382→  }
383→  to {
384→    opacity: 0;
385→    transform: scale(0.98);
386→  }
387→}
388→
389→@keyframes fade-and-scale-in {
390→  from {
391→    opacity: 0;
392→    transform: scale(1.02);
393→  }
394→  to {
395→    opacity: 1;
396→    transform: scale(1);
397→  }
398→}
399→
400→/* Navigation: fade only, no scale (stays anchored) */
401→::view-transition-old(navigation),
402→::view-transition-new(navigation) {
403→  animation-duration: 400ms;
404→  animation-timing-function: ease-in-out;
405→}
406→
407→::view-transition-old(navigation) {
408→  animation-name: fade-out-only;
409→}
410→
411→::view-transition-new(navigation) {
412→  animation-name: fade-in-only;
413→}
414→
415→/* Footer: fade only, no scale (stays anchored) */
416→::view-transition-old(footer),
