  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
  5→import { loadVimeoPlayer } from '@/lib/vimeo';
  6→import { useIsMobile } from '@/lib/hooks/useIsMobile';
  7→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
  8→
  9→/**
 10→ * HERO REEL - Homepage Autoplay Video
 11→ *
 12→ * Consistency guarantees:
 13→ * 1. Deterministic initialization with timeout (12s max)
 14→ * 2. Clean error handling with fallback to static state
 15→ * 3. Proper cleanup on unmount
 16→ * 4. Scroll-based pause/resume with ref tracking
 17→ * 5. Mobile optimization: static thumbnail only (no video player)
 18→ * 6. Error event listeners for runtime failures
 19→ */
 20→
 21→// Timeout for player initialization (12 seconds - supports slow connections)
 22→const INIT_TIMEOUT_MS = 12000;
 23→
 24→interface HeroReelProps {
 25→  videoId: string;
 26→  videoHash?: string;
 27→  startTime?: number;
 28→  thumbnail?: string;
 29→}
 30→
 31→export function HeroReel({ videoId, videoHash, startTime = 0, thumbnail }: HeroReelProps) {
 32→  const containerRef = useRef<HTMLDivElement>(null);
 33→  const playerRef = useRef<Player | null>(null);
 34→  const isReadyRef = useRef(false);
 35→  const scrolledDownRef = useRef(false);
 36→
 37→  const [scrollProgress, setScrollProgress] = useState(0);
 38→  const [heroRevealed, setHeroRevealed] = useState(false);
 39→
 40→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 41→  const prefersReducedMotion = usePrefersReducedMotion();
 42→
 43→  // Thumbnail URL - use provided thumbnail or fallback to Vimeo vumbnail
 44→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
 45→
 46→  // Hero height based on device
 47→  const heroHeight = isMobile ? '50vh' : '70vh';
 48→
 49→  // Clean destroy of player instance
 50→  const destroyPlayer = useCallback(() => {
 51→    if (playerRef.current) {
 52→      try {
 53→        playerRef.current.destroy();
 54→      } catch {
 55→        // Player may already be destroyed
 56→      }
 57→      playerRef.current = null;
 58→    }
 59→    isReadyRef.current = false;
 60→  }, []);
 61→
 62→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 63→  useEffect(() => {
 64→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 65→    return () => clearTimeout(revealTimer);
 66→  }, []);
 67→
 68→  // Initialize Vimeo player with autoplay (desktop only)
 69→  useEffect(() => {
 70→    // Wait for mobile detection to complete before deciding
 71→    if (!isMobileReady) return;
 72→
 73→    // Skip player initialization on mobile - use static thumbnail instead
 74→    if (isMobile) return;
 75→
 76→    if (!containerRef.current) return;
 77→
 78→    const baseConfig = {
 79→      muted: true,
 80→      loop: true,
 81→      autoplay: true,
 82→      controls: false,
 83→      background: true,
 84→      responsive: true,
 85→      title: false,
 86→      byline: false,
 87→      portrait: false,
 88→      dnt: true,
 89→      playsinline: true,
 90→      quality: 'auto',
 91→      speed: true,
 92→    };
 93→
 94→    const baseUrl = videoHash
 95→      ? `https://vimeo.com/${videoId}/${videoHash}`
 96→      : `https://vimeo.com/${videoId}`;
 97→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
 98→
 99→    let isMounted = true;
100→
101→    const initPlayer = async () => {
102→      try {
103→        const VimeoPlayer = await loadVimeoPlayer();
104→        if (!isMounted || !containerRef.current) return;
105→
106→        playerRef.current = new VimeoPlayer(containerRef.current!, {
107→          url: urlWithTime as `https://vimeo.com/${string}`,
108→          ...baseConfig
109→        });
110→
111→        // Race between ready() and timeout
112→        const readyPromise = playerRef.current.ready();
113→        const timeoutPromise = new Promise<never>((_, reject) => {
114→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
115→        });
116→
117→        await Promise.race([readyPromise, timeoutPromise]);
118→
119→        if (!isMounted) {
120→          destroyPlayer();
121→          return;
122→        }
123→
124→        isReadyRef.current = true;
125→
126→        // Add error event listener for runtime failures
127→        playerRef.current.on('error', (error) => {
128→          console.error('HeroReel: Player error', videoId, error);
129→          // Don't destroy - let video degrade gracefully to thumbnail
130→        });
131→
132→        // Start playback
133→        await playerRef.current.play().catch(() => {
134→          // Autoplay blocked - video will show loading state
135→        });
136→      } catch (err) {
137→        console.error('HeroReel: Player init failed', videoId, err);
138→        destroyPlayer();
139→      }
140→    };
141→
142→    initPlayer();
143→
144→    return () => {
145→      isMounted = false;
146→      destroyPlayer();
147→    };
148→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
149→
150→  // Track scroll for fade and pause/resume
151→  useEffect(() => {
152→    const handleScroll = () => {
153→      const scrollY = window.scrollY;
154→      const viewportHeight = window.innerHeight;
155→      // Use appropriate hero height multiplier based on device
156→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
157→      const introPadding = 160;
158→      const textStartPosition = heroHeightValue + introPadding;
159→      const oneThirdViewport = viewportHeight / 3;
160→      const fadeStartScroll = textStartPosition - oneThirdViewport;
161→
162→      const fadeRange = 200;
163→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
164→      setScrollProgress(progress);
165→
166→      // Pause/resume with ref tracking for consistency (desktop only)
167→      if (!isMobile) {
168→        const hasScrolledDown = scrollY > 10;
169→
170→        if (hasScrolledDown && !scrolledDownRef.current) {
171→          scrolledDownRef.current = true;
172→          if (playerRef.current && isReadyRef.current) {
173→            playerRef.current.pause().catch(() => {});
174→          }
175→        } else if (!hasScrolledDown && scrolledDownRef.current) {
176→          scrolledDownRef.current = false;
177→          if (playerRef.current && isReadyRef.current) {
178→            playerRef.current.play().catch(() => {});
179→          }
180→        }
181→      }
182→    };
183→
184→    // Run immediately to sync initial state
185→    handleScroll();
186→
187→    window.addEventListener('scroll', handleScroll, { passive: true });
188→    return () => window.removeEventListener('scroll', handleScroll);
189→  }, [isMobile]);
190→
191→  const scrollOpacity = 1 - scrollProgress;
192→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
193→  const heroScale = heroRevealed ? 1 : 1.02;
194→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
195→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
196→
197→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
198→  // This ensures scroll-driven fade is perfectly synchronized with navigation
199→  const heroTransition = heroRevealed
200→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
201→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
202→
203→  return (
204→    <div
205→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
206→      style={{
207→        height: heroHeight,
208→        zIndex: 0,
209→        backgroundColor: '#141414'
210→      }}
211→    >
212→      <div
213→        style={{
214→          width: '100%',
215→          height: '100%',
216→          opacity: heroOpacity,
217→          transform: `scale(${heroScale})`,
218→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
219→          transition: heroTransition,
220→          transformOrigin: 'center center',
221→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
222→        }}
223→      >
224→        {isMobile ? (
225→          // Mobile: Static thumbnail only (no video player)
226→          <div
227→            className="absolute inset-0 w-full h-full"
228→            style={{
229→              backgroundImage: `url(${thumbnailUrl})`,
230→              backgroundSize: 'cover',
231→              backgroundPosition: 'center',
232→              backgroundColor: '#141414',
233→              zIndex: 0
234→            }}
235→          />
236→        ) : (
237→          // Desktop: Vimeo player container
238→          <div
239→            ref={containerRef}
240→            className="absolute inset-0 w-full h-full"
241→            style={{
242→              backgroundColor: '#141414',
243→              zIndex: 0
244→            }}
245→          />
246→        )}
247→      </div>
248→    </div>
249→  );
250→}
