 1→'use client';
 2→
 3→import { useEffect, useRef, useState, ReactNode } from 'react';
 4→
 5→interface ScrollRevealProps {
 6→  children: ReactNode;
 7→  delay?: number;
 8→  className?: string;
 9→}
10→
11→/**
12→ * SCROLL REVEAL - Subtle entrance animation
13→ *
14→ * Restrained animation inspired by oddfellows.tv:
15→ * - Opacity fade from 0 to 1
16→ * - Subtle translateY (15px) for gentle lift
17→ * - 400ms duration - quick but not jarring
18→ * - Respects prefers-reduced-motion
19→ */
20→export function ScrollReveal({ children, delay = 0, className = '' }: ScrollRevealProps) {
21→  const ref = useRef<HTMLDivElement>(null);
22→  const [isVisible, setIsVisible] = useState(false);
23→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
24→
25→  useEffect(() => {
26→    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
27→    setPrefersReducedMotion(mediaQuery.matches);
28→
29→    const handleChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
30→    mediaQuery.addEventListener('change', handleChange);
31→    return () => mediaQuery.removeEventListener('change', handleChange);
32→  }, []);
33→
34→  useEffect(() => {
35→    const observer = new IntersectionObserver(
36→      ([entry]) => {
37→        if (entry.isIntersecting) {
38→          setIsVisible(true);
39→          observer.disconnect();
40→        }
41→      },
42→      { threshold: 0.1, rootMargin: '20px' }
43→    );
44→
45→    if (ref.current) observer.observe(ref.current);
46→    return () => observer.disconnect();
47→  }, []);
48→
49→  const easing = 'cubic-bezier(0.25, 0.1, 0.25, 1)';
50→  const duration = prefersReducedMotion ? 0 : 400;
51→
52→  return (
53→    <div
54→      ref={ref}
55→      className={className}
56→      style={{
57→        opacity: isVisible ? 1 : 0,
58→        transform: isVisible ? 'translateY(0)' : 'translateY(15px)',
59→        transition: prefersReducedMotion
60→          ? 'none'
61→          : `opacity ${duration}ms ${easing} ${delay}ms, transform ${duration}ms ${easing} ${delay}ms`
62→      }}
63→    >
64→      {children}
65→    </div>
66→  );
67→}
