 1→'use client';
 2→
 3→import { useRouter } from 'next/navigation';
 4→import { useCallback, useEffect, useTransition } from 'react';
 5→
 6→/**
 7→ * ViewTransitions - Cinematic page transitions using View Transitions API
 8→ *
 9→ * Design philosophy:
10→ * - Feels like film dissolves, not web animations
11→ * - Subtle crossfade with micro-scale for depth
12→ * - Duration: 350ms (matches site's --transition-smooth)
13→ * - Graceful fallback for unsupported browsers
14→ * - Respects prefers-reduced-motion
15→ */
16→
17→interface ViewTransitionsProps {
18→  children: React.ReactNode;
19→}
20→
21→export function ViewTransitions({ children }: ViewTransitionsProps) {
22→  const router = useRouter();
23→  const [isPending, startTransition] = useTransition();
24→
25→  const handleNavigation = useCallback((href: string) => {
26→    // Check for reduced motion preference
27→    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
28→
29→    // Check if View Transitions API is supported
30→    const supportsViewTransitions = 'startViewTransition' in document;
31→
32→    if (prefersReducedMotion || !supportsViewTransitions) {
33→      // Fallback: instant navigation
34→      startTransition(() => {
35→        router.push(href);
36→      });
37→      return;
38→    }
39→
40→    // Use View Transitions API for cinematic crossfade
41→    (document as any).startViewTransition(() => {
42→      startTransition(() => {
43→        router.push(href);
44→      });
45→    });
46→  }, [router, startTransition]);
47→
48→  useEffect(() => {
49→    // Intercept clicks on internal links
50→    const handleClick = (e: MouseEvent) => {
51→      const target = e.target as HTMLElement;
52→      const anchor = target.closest('a');
53→
54→      if (!anchor) return;
55→
56→      const href = anchor.getAttribute('href');
57→
58→      // Skip if:
59→      // - No href
60→      // - External link (starts with http and not our domain)
61→      // - Hash link (starts with #)
62→      // - New tab (target="_blank")
63→      // - Modified click (ctrl/cmd/shift/alt)
64→      // - Download link
65→      if (
66→        !href ||
67→        href.startsWith('http') ||
68→        href.startsWith('#') ||
69→        href.startsWith('mailto:') ||
70→        anchor.target === '_blank' ||
71→        e.ctrlKey ||
72→        e.metaKey ||
73→        e.shiftKey ||
74→        e.altKey ||
75→        anchor.hasAttribute('download')
76→      ) {
77→        return;
78→      }
79→
80→      // Prevent default and use our transition
81→      e.preventDefault();
82→      handleNavigation(href);
83→    };
84→
85→    document.addEventListener('click', handleClick);
86→    return () => document.removeEventListener('click', handleClick);
87→  }, [handleNavigation]);
88→
89→  return <>{children}</>;
90→}
