 1→'use client';
 2→
 3→import { useState, useEffect } from 'react';
 4→
 5→/**
 6→ * Shared mobile detection hook
 7→ *
 8→ * Uses matchMedia instead of resize listener — fires only at breakpoint,
 9→ * not every pixel. Combines touch detection with viewport width.
10→ *
11→ * Returns { isMobile, isReady }:
12→ * - isMobile: true on touch devices OR viewports < 768px
13→ * - isReady: true after hydration (prevents SSR/client mismatch race conditions)
14→ */
15→export function useIsMobile(): { isMobile: boolean; isReady: boolean } {
16→  const [isMobile, setIsMobile] = useState(true); // Default to mobile (safer — avoids initializing heavy desktop features)
17→  const [isReady, setIsReady] = useState(false);
18→
19→  useEffect(() => {
20→    const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
21→    const mq = window.matchMedia('(max-width: 767px)');
22→
23→    const update = () => setIsMobile(isTouchDevice || mq.matches);
24→
25→    update();
26→    setIsReady(true);
27→
28→    const handler = (e: MediaQueryListEvent) => setIsMobile(isTouchDevice || e.matches);
29→    mq.addEventListener('change', handler);
30→
31→    return () => mq.removeEventListener('change', handler);
32→  }, []);
33→
34→  return { isMobile, isReady };
35→}
