14→export function RotatingTitle() {
15→  const [currentIndex, setCurrentIndex] = useState(0);
16→  const [isVisible, setIsVisible] = useState(true);
17→
18→  useEffect(() => {
19→    // Rotation interval: 4s display + 0.5s transition = 4.5s per title
20→    const rotationInterval = setInterval(() => {
21→      // Fade out
22→      setIsVisible(false);
23→
24→      // After fade out, change text and fade in
25→      setTimeout(() => {
26→        setCurrentIndex((prev) => (prev + 1) % titles.length);
27→        setIsVisible(true);
28→      }, 500); // Match CSS transition duration
29→    }, 4000); // Display each title for 4 seconds
30→
31→    return () => clearInterval(rotationInterval);
32→  }, []);
33→
34→  return (
35→    <div
36→      className="text-base md:text-lg transition-opacity duration-500 ease-in-out"
37→      style={{
38→        color: '#8a8a8a',
39→        fontWeight: 400,
40→        fontFamily: 'var(--font-display)',
41→        opacity: isVisible ? 1 : 0,
42→        minHeight: '1.5em' // Prevent layout shift during transitions
43→      }}
44→      aria-live="polite"
45→      aria-atomic="true"
46→    >
47→      {titles[currentIndex]}
48→    </div>
49→  );
50→}
